echo "------------------------------"

# Create namespace
echo "📦 Creating Kubernetes namespace..."
kubectl create namespace ${NAMESPACE} --dry-run=client -o yaml | kubectl apply -f -
echo "✅ Namespace: ${NAMESPACE} ready"

# SSL/TLS Configuration
echo "🔒 Setting up SSL/TLS certificates..."
cat <<EOF | kubectl apply -f -
apiVersion: v1
kind: Secret
metadata:
  name: vision-maestra-tls
  namespace: ${NAMESPACE}
type: kubernetes.io/tls
data:
  tls.crt: $(echo "placeholder-cert" | base64 -w 0)
  tls.key: $(echo "placeholder-key" | base64 -w 0)
EOF
echo "✅ SSL/TLS: Configured (certificates pending real setup)"

# Redis for WebSocket clustering
echo "🔄 Setting up Redis for WebSocket clustering..."
cat <<EOF | kubectl apply -f -
apiVersion: apps/v1
kind: Deployment
metadata:
  name: redis
  namespace: ${NAMESPACE}
spec:
  replicas: 1
  selector:
    matchLabels:
      app: redis
  template:
    metadata:
      labels:
        app: redis
    spec:
      containers:
      - name: redis
        image: redis:7-alpine
        ports:
        - containerPort: 6379
        resources:
          requests:
            memory: "256Mi"
            cpu: "100m"
          limits:
            memory: "512Mi"
            cpu: "200m"
---
apiVersion: v1
kind: Service
metadata:
  name: redis
  namespace: ${NAMESPACE}
spec:
  selector:
    app: redis
  ports:
  - port: 6379
    targetPort: 6379
EOF
echo "✅ Redis: Deployed for WebSocket clustering"

# Phase 3: Application Deployment
echo ""
