# Deploy Visión Maestra platform
echo "🎯 Deploying Visión Maestra 6-Component Platform..."
cat <<EOF | kubectl apply -f -
apiVersion: apps/v1
kind: Deployment
metadata:
  name: vision-maestra
  namespace: ${NAMESPACE}
  labels:
    app: vision-maestra
    version: "1.0.0"
spec:
  replicas: 3
  selector:
    matchLabels:
      app: vision-maestra
  template:
    metadata:
      labels:
        app: vision-maestra
    spec:
      containers:
      - name: vision-maestra
        image: ghcr.io/jlma-agentic-ai/contexto/vision-maestra:${IMAGE_TAG}
        ports:
        - containerPort: 3000
          name: http
        - containerPort: 8080
          name: api
        - containerPort: 8081
          name: websocket
        env:
        - name: NODE_ENV
          value: "production"
        - name: REDIS_URL
          value: "redis://redis:6379"
        - name: LOG_LEVEL
          value: "info"
        resources:
          requests:
            memory: "512Mi"
            cpu: "250m"
          limits:
            memory: "1Gi"
            cpu: "500m"
        livenessProbe:
          httpGet:
            path: /health
            port: 3000
          initialDelaySeconds: 30
          periodSeconds: 10
        readinessProbe:
          httpGet:
            path: /health
            port: 3000
          initialDelaySeconds: 5
          periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: vision-maestra
  namespace: ${NAMESPACE}
spec:
  selector:
    app: vision-maestra
  ports:
  - name: http
    port: 80
    targetPort: 3000
  - name: api
    port: 8080
    targetPort: 8080
  - name: websocket
    port: 8081
    targetPort: 8081
  type: ClusterIP
EOF
echo "✅ Application: Deployed with 3 replicas"

# Load Balancer with Sticky Sessions
echo "⚖️ Setting up load balancer with sticky sessions..."
cat <<EOF | kubectl apply -f -
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: vision-maestra-ingress
  namespace: ${NAMESPACE}
  annotations:
    kubernetes.io/ingress.class: "nginx"
    nginx.ingress.kubernetes.io/ssl-redirect: "true"
    nginx.ingress.kubernetes.io/websocket-services: "vision-maestra"
    nginx.ingress.kubernetes.io/affinity: "cookie"
    nginx.ingress.kubernetes.io/affinity-mode: "persistent"
spec:
  tls:
  - hosts:
    - vision-maestra.prod
    secretName: vision-maestra-tls
  rules:
  - host: vision-maestra.prod
    http:
      paths:
      - path: /
        pathType: Prefix
        backend:
          service:
            name: vision-maestra
            port:
              number: 80
      - path: /api
        pathType: Prefix
        backend:
          service:
            name: vision-maestra
            port:
              number: 8080
      - path: /ws
        pathType: Prefix
        backend:
          service:
            name: vision-maestra
            port:
              number: 8081
EOF
echo "✅ Load Balancer: Configured with sticky sessions"

