cat <<EOF | kubectl apply -f -
apiVersion: v1
kind: ConfigMap
metadata:
  name: monitoring-config
  namespace: ${NAMESPACE}
data:
  config.yml: |
    targets:
      - vision-maestra:3000/health
      - vision-maestra:8080/api/health
    thresholds:
      response_time: 200ms
      error_rate: 1%
      availability: 99.9%
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: monitoring
  namespace: ${NAMESPACE}
spec:
  replicas: 1
  selector:
    matchLabels:
      app: monitoring
  template:
    metadata:
      labels:
        app: monitoring
    spec:
      containers:
      - name: monitoring
        image: prom/prometheus:latest
        ports:
        - containerPort: 9090
        volumeMounts:
        - name: config
          mountPath: /etc/prometheus
        resources:
          requests:
            memory: "256Mi"
            cpu: "100m"
          limits:
            memory: "512Mi"
            cpu: "200m"
      volumes:
      - name: config
        configMap:
          name: monitoring-config
EOF
echo "✅ Monitoring: Deployed with health tracking"

